+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+/**
+ * The same behaviour as {@link ContactViewTest}, driven through Chromium.
+ * Named *IT so it stays out of the fast {@code mvn -o test} run; start it with
+ * {@code mvn -o test -Dtest=ContactBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactBrowserIT extends AbstractBasePlaywrightIT {
+
+    private static final String DIALOG_HEADER = "Leave this page?";
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator link(String text) {
+        return page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName(text));
+    }
+
+    private DialogElement confirmation() {
+        return DialogElement.getByHeaderText(page, DIALOG_HEADER);
+    }
+
+    /** Waits for the view to be there, rather than for a round trip to end. */
+    private void assertHeading(String heading) {
+        assertThat(page.locator("h1")).hasText(heading);
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private void fillIn(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        name().setValue(nameValue);
+        email().setValue(emailValue);
+        phone().setValue(phoneValue);
+        message().setValue(messageValue);
+        waitForVaadin();
+    }
+
+    /** Sends and waits until the notification proves the round trip is over. */
+    private void sendSuccessfully() {
+        send().click();
+        assertThat(page.locator("vaadin-notification-card"))
+                .containsText("Message sent");
+    }
+
+    @Test
+    void theFormIsThereAndSendIsEnabled() {
+        assertHeading("Contact");
+        assertThat(link("About")).isVisible();
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+    }
+
+    @Test
+    void anEmptyFormReportsEveryFailedRule() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        new NotificationElement(page).assertClosed();
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+        send().assertEnabled();
+    }
+
+    @Test
+    void aMalformedAddressIsReported() {
+        fillIn("Ada", "ada@", "", "Hello");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Ada");
+        new NotificationElement(page).assertClosed();
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void anOverlongMessageIsReported() {
+        fillIn("Ada", "ada@example.com", "", "x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void sendingNotifiesListsAndResetsTheForm() {
+        fillIn("Ada Lovelace", "ada@example.com", "", "Hello from the browser");
+        sendSuccessfully();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertCellContent(0, 0, "Ada Lovelace");
+        grid.assertCellContent(0, 1, "Hello from the browser");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("G");
+        send().assertEnabled();
+    }
+
+    @Test
+    void newestFirstAndSurvivesLeavingTheView() {
+        fillIn("Ada", "", "123", "First");
+        sendSuccessfully();
+        fillIn("Grace", "", "456", "Second");
+        sendSuccessfully();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertCellContent(0, 0, "Grace");
+        grid.assertCellContent(1, 0, "Ada");
+
+        link("About").click();
+        assertHeading("About");
+
+        link("Contact").click();
+        assertHeading("Contact");
+        assertThat(page.getByText("Grace",
+                new Page.GetByTextOptions().setExact(true))).isVisible();
+        GridElement.get(page).assertCellContent(0, 0, "Grace");
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        fillIn("Ada", "ada@example.com", "", "Sent with the keyboard");
+        name().getLocator().press("Enter");
+
+        assertThat(page.locator("vaadin-notification-card"))
+                .containsText("Message sent");
+        GridElement.get(page).assertCellContent(0, 1, "Sent with the keyboard");
+    }
+
+    @Test
+    void anEmptyFormLeavesWithoutAskingAndWithoutReloading() {
+        page.evaluate("() => { window.__stillTheSamePage = true; }");
+
+        link("About").click();
+        assertHeading("About");
+
+        assertTrue(page.url().endsWith("/about"));
+        assertEquals(Boolean.TRUE,
+                page.evaluate("() => window.__stillTheSamePage === true"),
+                "the router navigated without reloading the page");
+        confirmation().assertClosed();
+    }
+
+    @Test
+    void keepEditingStaysOnTheForm() {
+        name().setValue("Ada");
+        waitForVaadin();
+
+        link("About").click();
+        confirmation().assertOpen();
+
+        ButtonElement
+                .getByText(confirmation().getFooterLocator(), "Keep editing")
+                .click();
+
+        confirmation().assertClosed();
+        assertHeading("Contact");
+        name().assertValue("Ada");
+        assertTrue(page.url().endsWith("/contact"));
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        message().setValue("Half written");
+        waitForVaadin();
+
+        link("About").click();
+        confirmation().assertOpen();
+
+        ButtonElement.getByText(confirmation().getFooterLocator(), "Discard")
+                .click();
+
+        assertHeading("About");
+        assertTrue(page.url().endsWith("/about"));
+    }
+
+    @Test
+    void nothingIsAskedAfterAFreshSend() {
+        fillIn("Ada", "", "123", "Bye");
+        sendSuccessfully();
+
+        link("About").click();
+        assertHeading("About");
+        confirmation().assertClosed();
+    }
+}
